class TwinHandler(Handler):
    def do_POST(self):
        body=self.rfile.read(min(int(self.headers.get('Content-Length','0')),2_000_000))
        self.respond(body=body)

    def respond(self, head=False, body=b''):
        parsed=urlsplit(self.path);path=parsed.path;case=parse_qs(parsed.query).get('case',['success'])[0]
        self.server.counts[path]+=1
        status,kind,response=200,'text/html',''
        if path=='/twin/login':
            self.send_response(200);self.send_header('Set-Cookie','synthetic_portal=authenticated; Path=/; HttpOnly');self.end_headers();return
        if path in {'/twin/invalid-login','/twin/upload-attempt','/twin/eoi-checkbox-toggle'}: response='recorded'
        elif path=='/twin/jwt':
            status=401 if case in {'expired','invalid'} else 200;kind='application/json';response=json.dumps({'access_token':'synthetic.runtime.jwt'})
        elif path in {'/twin/aro','/twin/mule','/twin/kafka'}:
            kind='application/json'
            required_headers=True
            if path!='/twin/kafka':
                try:group=json.loads(body).get('groupNumber')
                except (ValueError,AttributeError):group=None
                self.server.benefits_requests.append({'path':path,'groupNumber':group,'headers':dict(self.headers)})
                required_headers=(self.headers.get('client_id')==BENEFITS_CLIENT_ID and self.headers.get('Content-Type')=='application/json' and self.headers.get('Authorization')=='Bearer synthetic.runtime.jwt' and not self.headers.get('Cookie'))
            if not required_headers:status,response=400,'{"error":"Required synthetic benefits headers missing or incorrect"}'
            elif case in {'expired','invalid'}:status,response=401,'{}'
            elif case=='500':status,response=500,'{}'
            elif case=='malformed':response='{broken'
            elif case=='timeout':time.sleep(.25);response='{}'
            elif case=='empty':response='[]' if path!='/twin/kafka' else ''
            elif path=='/twin/kafka':response='[{"id":1}]'
            else:response=json.dumps([{'lastName':''},{'lastName':'SYNTHETIC'}] if case in {'multi','mixed','success'} else [{'lastName':'SYNTHETIC'}])
        elif path=='/twin/soap':
            kind='text/xml';response='' if case=='empty' else '<s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/"><s:Body><response>synthetic</response></s:Body></s:Envelope>'
            if case=='500':status=500
        elif path in {'/twin/MemberSearchVFPage_ACE', '/twin/benefit'}:
            from .retained_pages import teledent_frame
            response=teledent_frame(case, path.endswith('/benefit'))
        elif path.startswith('/star/sharedpages/') or path=='/twin/APP00005161':
            if not self.headers.get('Authorization'):
                self.send_response(401);self.send_header('WWW-Authenticate','Basic realm="FINEOS Web Application"');self.end_headers();return
            if path=='/twin/APP00005161':
                self.send_response(302);self.send_header('Location','/star/sharedpages/workmanager');self.end_headers();return
            response=app_page('APP00005161',case,path)
        elif path.startswith('/twin/APP'):
            app=path.split('/')[-1]
            if case=='500':status,response=500,'Synthetic server failure'
            elif app in PORTAL and 'synthetic_portal=authenticated' not in self.headers.get('Cookie',''):
                response=login_page(app,'',portal=True)
            else:response=app_page(app,case,path)
        else:
            return super().respond(head)
        data=response.encode()
        self.send_response(status);self.send_header('Content-Type',kind+'; charset=utf-8');self.send_header('Content-Length',str(len(data)));self.end_headers()
        if not head:
            try:self.wfile.write(data)
            except (BrokenPipeError,ConnectionResetError,ConnectionAbortedError):pass


class QuietTwinServer(ThreadingHTTPServer):
    def handle_error(self, request, client_address):
        # Synthetic clients intentionally close navigation/timeout sockets.
        pass


def make_twin_server(port=0):
    server=QuietTwinServer(('127.0.0.1',port),TwinHandler);server.counts=Counter();server.benefits_requests=[];return server


def mock_catalog(apps, base, cases=None):
