    import copy
    from pathlib import Path
    cases=cases or {};apps=copy.deepcopy(apps)
    for app in apps:
        code=app['app_id'];case=cases.get(code,'success')
        for index,endpoint in enumerate(app['urls']):endpoint['url']=f'{base}/twin/{code}?case={case}';endpoint['label']=endpoint['label'] or str(index)
        if app.get('functional_url'):app['functional_url']=f'{base}/twin/{code}?case={case}'
        if app.get('portal_login_url'):app['portal_login_url']=f'{base}/twin/APP00005034'
        for step in app.get('steps',[]):
            if 'timeout' in step: step['timeout']=2
        app['action_timeout']=2;app['allow_http_credentials']=True
